checkSpec:
PREFIX chorus: <https://jeffbridwell.com/chorus#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT DISTINCT ?d WHERE {
  GRAPH ?g { ?d a chorus:Domain }
  FILTER NOT EXISTS { GRAPH ?h { ?d a owl:Class } }
}

PREFIX chorus: <https://jeffbridwell.com/chorus#>
SELECT DISTINCT ?v WHERE {
  GRAPH ?g { ?s a chorus:Property ; chorus:propertyKey ?v }
  FILTER NOT EXISTS { GRAPH ?h { ?k a chorus:PropertyKey ; chorus:keyName ?kn ; chorus:appliesToClass ?c ; chorus:propertyKind ?t } FILTER(STR(?kn) = STR(?v)) }
}

PREFIX jb: <https://jeffbridwell.com/ontology#>
SELECT DISTINCT ?g WHERE {
  GRAPH ?g { ?s ?p ?o }
  FILTER(STRSTARTS(STR(?g), "urn:gathering:") && !STRSTARTS(STR(?g), "urn:gathering:icd"))
  FILTER NOT EXISTS { GRAPH ?g { ?x jb:hasVisibility ?v } }
}

PREFIX chorus: <https://jeffbridwell.com/chorus#>
SELECT DISTINCT ?d WHERE {
  GRAPH ?g { ?d a chorus:Domain }
  FILTER NOT EXISTS { GRAPH ?h { ?f a chorus:FitnessFunction ; ?p ?d } }
}
